  F.active=1;F.frame=0;F.phase=0;F.clock=0;

 }
 if(DEAD || !RIC->id || RIC->flags&0x100 || RIC->step>=0x40 || U32(0x801d169c)) {
  Clear();nativeThink();return;
 }
 U16(0x801d15f4)=2; U32(0x801d15ec)=0;
 if(F.frame>=300) {Clear();nativeThink();return;}
 // Let Alucard fall.
