   u8 old=U8(0x801814f3);U8(0x801814f3)=0x3f;
   s32 made=ricCrash();U8(0x801814f3)=old;
   if(made) {
    Tag();F.phase=1;F.frame=0;GRAB=1;ENT->unkb8=(Entity*)RIC;U16(0x80072f82)=0x5243;U16(0x80072f84)=0;
   }
