 s32 ex=e->x>>16,ey=e->y>>16,px=ENT->x>>16,py=ENT->y>>16;
 ex+=e->face?-e->offx:e->offx;
 px+=ENT->face?-ENT->offx:ENT->offx;
 ey+=e->offy;py+=ENT->offy;
 s32 dx=ex-px,dy=ey-py;if(dx<0)dx=-dx;if(dy<0)dy=-dy;
 if(dx>(s32)e->width+(s32)ENT->width || dy>(s32)e->height+(s32)ENT->height)return;
 // Each hit takes ten HP.
 e->ext[10]=0;e->hitflags=0x80;e->step=3;*(s16*)((u8*)e+0x7c)=4;
